param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Read-only selected gameplay evidence. Full derived C# stays local.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$out=Join-Path $root 'docs/research/rimworld/evidence'
function Source([string]$file,[int]$start=1,[int]$end=0){
 $p=Join-Path $root $file;$lines=Get-Content -LiteralPath $p
 if(!$end){$end=$lines.Count};if($start -lt 1 -or $end -gt $lines.Count -or $end -lt $start){throw "Invalid range $file"}
 [ordered]@{file=$file;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant();lines=@($start,$end)}
}
$claims=@(
 [ordered]@{id='FR01';finding='Minifiable means minifiedDef exists. FurnitureBase supplies MinifiedThing; furniture quality/bed components are inherited separately. MakeMinified despawns the original and places that same Thing inside a new one-stack wrapper; no new furniture or quality roll is created.';sources=@((Source '.local-research/energy/Verse.ThingDef.cs' 536 544),(Source '.local-research/furniture-reinstall/RimWorld.MinifyUtility.cs'),(Source '.local-research/furniture-reinstall/RimWorld.MinifiedThing.cs' 15 48));xml=@('FRX01','FRX02')},
 [ordered]@{id='FR02';finding='Wrapper and inner object have separate IDs and hit points. MinifiedThing deep-saves its one-stack innerContainer; inspect text delegates to the inner furniture but its health bar belongs to the wrapper. Normal reinstall clears InnerThing before destroying the wrapper and returns the existing inner entity.';sources=@((Source '.local-research/furniture-reinstall/RimWorld.MinifiedThing.cs'),(Source '.local-research/furniture-reinstall/RimWorld.Blueprint_Install.cs' 104 149));xml=@('FRX03')},
 [ordered]@{id='FR03';finding='Explicit Uninstall uses JobDriver_RemoveBuilding: default building.uninstallWork200, workLeft decreases ConstructionSpeed*1.7*delta, serialized progress belongs to that job. The driver does not award Construction XP. FinishedRemoving uninstalls and increments ThingsUninstalled. ActiveSkill is not XP gain.';sources=@((Source '.local-research/generation/RimWorld.BuildingProperties.cs' 43 52),(Source '.local-research/skills/RimWorld.JobDriver_RemoveBuilding.cs'),(Source '.local-research/furniture-reinstall/RimWorld.JobDriver_Uninstall.cs'));xml=@('FRX04')},
 [ordered]@{id='FR04';finding='InstallJob creates HaulToContainer with source A, install blueprint B and count1. It checks source reachability, forbidden/reservation and another pawn carrying it; the driver reserves both. It walks to source, optionally uninstalls a still-installed source, carries it to B, steps out of footprint, replaces blueprint with the original furniture and deposits.';sources=@((Source '.local-research/work/RimWorld.WorkGiver_ConstructDeliverResources.cs' 367 400),(Source '.local-research/furniture-reinstall-extra/Verse.AI.JobDriver_HaulToContainer.cs'),(Source '.local-research/furniture-reinstall-extra/RimWorld.Toils_Construct.cs'));xml=@('FRX04')},
 [ordered]@{id='FR05';finding='Blueprint_Install WorkTotal150 is inspect-display work. HaulToContainer Duration returns0 for a non-Building destination, including a blueprint; the displayed150 must not be converted into a150-tick installation timer. Install blueprint material cost is empty and no Frame/quality reroll is used. Optional uninstall uses the200-work path; unlike explicit Uninstall it does not increment ThingsUninstalled there.';sources=@((Source '.local-research/furniture-reinstall/RimWorld.Blueprint_Install.cs'),(Source '.local-research/furniture-reinstall-extra/RimWorld.Blueprint.cs'),(Source '.local-research/furniture-reinstall-extra/Verse.AI.JobDriver_HaulToContainer.cs'),(Source '.local-research/furniture-reinstall-extra/RimWorld.Toils_Construct.cs'));xml=@()},
 [ordered]@{id='FR06';finding='Ordinary colonist bed ownership is temporarily unclaimed on despawn and cached in uninstalledAssignedPawns. Spawn tries to restore only valid pawns with no newly owned bed and compatible assignment status, then clears the cache. Both current and temporary owner lists serialize; restoration is conditional, not an unconditional overwrite.';sources=@((Source '.local-research/furniture-reinstall-extra/RimWorld.CompAssignableToPawn.cs' 183 237),(Source '.local-research/furniture-reinstall/RimWorld.CompAssignableToPawn_Bed.cs'),(Source '.local-research/housing/RimWorld.Pawn_Ownership.cs'));xml=@()},
 [ordered]@{id='FR07';finding='Building_Bed DeSpawn except WillReplace resets ForOwnerType to Colonist, Medical=false and alreadySetDefaultMed=false. Setters can remove owners before generic uninstalled-owner caching. Spawn can reapply default medical or prison-room rules. Original medical/prisoner flags are not generally retained by relocation.';sources=@((Source '.local-research/housing/RimWorld.Building_Bed.cs' 92 126),(Source '.local-research/housing/RimWorld.Building_Bed.cs' 251 307));xml=@()},
 [ordered]@{id='FR08';finding='CompGatherSpot serializes active. Despawn unregisters from the gather-spot lister without clearing active; player-owned spawn preserves it and registers. This component differs from the bed purpose reset; preserving entity identity does not imply every operational flag has the same lifecycle.';sources=@((Source '.local-research/social-interaction-extra/RimWorld.CompGatherSpot.cs'));xml=@('FRX02')},
 [ordered]@{id='FR09';finding='Starting the install designator cancels previous install blueprints for the source, matched through inner identity across maps. Placement uses normal CanPlaceBlueprintAt with source/inner exceptions; identical source location and rotation are rejected. Canceling a blueprint does not destroy the original furniture.';sources=@((Source '.local-research/furniture-reinstall/RimWorld.Designator_Install.cs'),(Source '.local-research/furniture-reinstall/RimWorld.InstallBlueprintUtility.cs'),(Source '.local-research/furniture-reinstall/RimWorld.Blueprint_Install.cs'));xml=@()},
 [ordered]@{id='FR10';finding='Before replacing an install blueprint, FirstBlockingThing is checked; failure ends the job Incompletable before unpacking. WorkGiver can instead request plant cutting/hauling/removal for some blockers. Cancelled or missing destination fails HaulToContainer. Exact generic interrupted-carry drop location is not established by these selected sources.';sources=@((Source '.local-research/furniture-reinstall-extra/RimWorld.Blueprint.cs'),(Source '.local-research/skills/RimWorld.GenConstruct.cs'),(Source '.local-research/furniture-reinstall-extra/RimWorld.WorkGiver_ConstructDeliverResourcesToBlueprints.cs'),(Source '.local-research/furniture-reinstall-extra/Verse.AI.JobDriver_HaulToContainer.cs'));xml=@()},
 [ordered]@{id='FR11';finding='Destroying a wrapper while its inner still exists cancels install blueprints and destroys the contained thing, with leavings depending on destroy mode. Successful reinstall first detaches inner, so wrapper destruction does not destroy that furniture. Trading also cancels install plans. Installed Building.Destroy cancels related plans.';sources=@((Source '.local-research/furniture-reinstall/RimWorld.MinifiedThing.cs' 225 263),(Source '.local-research/furniture-reinstall/RimWorld.Blueprint_Install.cs' 104 125),(Source '.local-research/energy/Verse.Building.cs'));xml=@()},
 [ordered]@{id='FR12';finding='Ordinary MinifiedThing has no parent or statBases. DeteriorationRate default base0 and no minifiedThingInherits; that StatDef bool defaults false. StatWorker only redirects to inner when explicitly flagged. Quality can be read from inner but0*factor stays0. FinalDeteriorationRate returns0 for nonpositive stat. This static result is not a long outdoor damage trial.';sources=@((Source '.local-research/apparel/RimWorld.StatDef.cs' 122 132),(Source '.local-research/housing/RimWorld.StatWorker.cs' 75 95),(Source '.local-research/housing/RimWorld.StatWorker.cs' 1253 1268),(Source '.local-research/furniture-reinstall-stats/RimWorld.StatExtension.cs'),(Source '.local-research/weather/RimWorld.SteadyEnvironmentEffects.cs' 254 312),(Source '.local-research/weapons/RimWorld.QualityUtility.cs' 19 45));xml=@('FRX03','FRX05')}
)
$specs=@(
 @('FRX01','Data/Core/Defs/ThingDefs_Buildings/Buildings_Base.xml','/Defs/ThingDef[@Name="BuildingBase"]'),
 @('FRX02','Data/Core/Defs/ThingDefs_Buildings/Buildings_Furniture.xml','/Defs/ThingDef[@Name="FurnitureBase" or @Name="FurnitureWithQualityBase" or @Name="ArtableFurnitureBase" or @Name="TableBase" or @Name="TableGatherSpotBase" or @Name="BedBase" or @Name="BedWithQualityBase" or @Name="ArtableBedBase" or @Name="SansComfortBedBase" or @Name="BasicBedBase" or defName="Bed" or defName="DiningChair" or defName="Table1x2c"]'),
 @('FRX03','Data/Core/Defs/ThingDefs_Items/Items_Unfinished.xml','/Defs/ThingDef[@Name="MinifiedThing"]'),
 @('FRX04','Data/Core/Defs/JobDefs/Jobs_Work.xml','/Defs/JobDef[defName="HaulToContainer" or defName="Uninstall"]'),
 @('FRX05','Data/Core/Defs/Stats/Stats_Basics_General.xml','/Defs/StatDef[defName="DeteriorationRate" or defName="MaxHitPoints"]')
)
$keep=@('defName','thingClass','category','useHitPoints','tickerType','stackLimit','statBases','comps','building','minifiedDef','size','alwaysHaulable','driverClass','reportString','defaultBaseValue','minValue','parts','minifiedThingInherits')
$xml=@(foreach($spec in $specs){
 $path=Join-Path $GameRoot $spec[1];$doc=[xml](Get-Content $path -Raw);$nodes=$doc.SelectNodes($spec[2]);if(!$nodes.Count){throw "Empty $($spec[0])"}
 $selected=@(foreach($node in $nodes){$copy=$node.CloneNode($false);foreach($child in $node.ChildNodes){if($child.LocalName -in $keep){[void]$copy.AppendChild($child.CloneNode($true))}};$copy.OuterXml})
 [ordered]@{id=$spec[0];file=$spec[1];source_sha256=(Get-FileHash $path).Hash.ToLowerInvariant();xpath=$spec[2];projection='Original attributes and selected gameplay children; full furniture parent chains retained';nodes=$selected}
})
$manifest=Get-Content (Join-Path $out 'furniture-reinstall-manifest.json') -Raw|ConvertFrom-Json
$prior=Get-Content (Join-Path $out 'furniture-quality-evidence.json') -Raw|ConvertFrom-Json
$e=[ordered]@{evidence_id='RW17-FURNITURE-REINSTALL-MECHANISMS';date_local='2026-11-04';version_text=$manifest.version_text;source_sha256=$manifest.source_sha256;kind='Static derived C# and shipped Core XML; native identity sample separate';manifests=@('furniture-reinstall','furniture-reinstall-extra','furniture-reinstall-stats','energy','housing','skills','work','social-interaction-extra','apparel','weather','weapons','generation');claims=$claims;xml=$xml;rea_members=$prior.rea_members;limitations=@('Derived C# is not original source.','REA67108864byte member-budget failure retained; not retried.','Selected Core XML is not a fully patched effective Def database.','Bed medical/prisoner, table-gather, damage, cancellation and obstruction branches were not executed in this runtime sample.')}
[IO.File]::WriteAllText((Join-Path $out 'furniture-reinstall-evidence.json'),($e|ConvertTo-Json -Depth 20).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"$($claims.Count) claims; $($xml.Count) XML selections."
